create table if not exists accountability_reports (analyzed_at date, created_at timestamp(6), updated_at timestamp(6), contract_id uuid not null, id uuid not null, responsible_id uuid not null, observation TEXT, status varchar(255) not null check ((status in ('UNDER_REVIEW','PENDING','UNDER_DILIGENCE','REJECTED','APPROVED'))), primary key (id));
create table if not exists agenda_events (end_date date, end_time time(0), start_date date not null, start_time time(0), created_at timestamp(6), updated_at timestamp(6), city_hall_id uuid not null, created_by_id uuid, id uuid not null, task_id uuid, type varchar(20) not null check ((type in ('MEETING','DEADLINE','SERVICE','CEREMONY','OTHER'))), title varchar(160) not null, location varchar(180), description TEXT, primary key (id));
create table if not exists agricultural_drivers (active boolean not null, city_hall_id uuid not null, id uuid not null, name varchar(140) not null, primary key (id), constraint agri_driver_city_name_uk unique (city_hall_id, name));
create table if not exists agricultural_machinery (active boolean not null, city_hall_id uuid not null, id uuid not null, name varchar(140) not null, primary key (id), constraint agri_machine_city_name_uk unique (city_hall_id, name));
create table if not exists agricultural_operational_controls (final_hour_meter numeric(12,2), initial_hour_meter numeric(12,2), created_at timestamp(6), updated_at timestamp(6), id uuid not null, machinery_id uuid, service_request_id uuid not null unique, tractor_driver_id uuid, primary key (id));
create table if not exists agricultural_payment_types (active boolean not null, city_hall_id uuid not null, id uuid not null, name varchar(100) not null, primary key (id), constraint agri_payment_city_name_uk unique (city_hall_id, name));
create table if not exists agricultural_service_requests (amount numeric(12,2), donation boolean not null, funder_amount numeric(12,2), payment_date date, requested_hours numeric(7,2), scheduled_date date, created_at timestamp(6), updated_at timestamp(6), city_hall_id uuid not null, client_id uuid not null, created_by_id uuid, id uuid not null, payment_proof_type_id uuid, service_type_id uuid not null, protocol varchar(40), funder_id varchar(80), payment_proof_content_type varchar(120), address varchar(1000), donation_origin varchar(1000), payment_proof_name varchar(255), status varchar(255) check ((status in ('CANCELLED','COMPLETED','PENDING','EXPIRED','UNPAID','IN_DEBT'))), payment_proof oid, primary key (id), constraint agri_protocol_city_uk unique (city_hall_id, protocol));
create table if not exists agricultural_service_types (active boolean not null, hourly_value numeric(12,2) not null, city_hall_id uuid not null, id uuid not null, name varchar(140) not null, area varchar(255) check ((area in ('URBAN','RURAL'))), primary key (id), constraint agri_type_city_name_uk unique (city_hall_id, name));
create table if not exists analyses (analyzed_at timestamp(6), created_at timestamp(6), updated_at timestamp(6), analyzed_by_id uuid, id uuid not null, requisition_id uuid, observation varchar(255), result varchar(255) check ((result in ('PENDENTE','APROVADO','CORRECAO_NECESSARIA','REPROVADO','CANCELADO'))), stage varchar(255) check ((stage in ('REQUISICAO_CADASTRADA','HOMOLOGACAO_SECRETARIO','RECEBIMENTO_COMPRAS','ANALISE_REQUISICAO','HOMOLOGACAO_COMPRAS','COMPOSICAO_PROCESSO','PROCESSO_LICITATORIO','SETOR_CONTRATOS','INICIO_SERVICOS','EMISSAO_EMPENHO','DECLARACAO_PAGAMENTO','EXECUCAO_PAGAMENTO','PRESTACAO_CONTAS','ANALISE_PRESTACAO_CONTAS','HOMOLOGACAO_PRESTACAO_CONTAS'))), primary key (id));
create table if not exists approvals (approved_at timestamp(6), created_at timestamp(6), updated_at timestamp(6), approved_by_id uuid, id uuid not null, requisition_id uuid, approval_sector varchar(255) check ((approval_sector in ('REQUISICAO_SECRETARIO','ANALISE_COMPRAS','DECLARACAO_PAGAMENTO','PRESTACAO_CONTAS'))), approval_status varchar(255) check ((approval_status in ('PENDENTE','APROVADO','REPROVADO'))), observation varchar(255), primary key (id));
create table if not exists audit_events (response_status integer not null, created_at timestamp(6) not null, id bigint generated by default as identity, method varchar(10) not null, actor_id uuid, city_hall_id uuid not null, event_hash varchar(64) not null unique, previous_hash varchar(64) not null, remote_address varchar(80), actor_email varchar(180) not null, user_agent varchar(400), path varchar(500) not null, primary key (id));
create table if not exists blacklisted_tokens (expires_at timestamp(6) not null, token varchar(2000) not null, primary key (token));
create table if not exists blocked_attempts (permanently_blocked boolean not null, total_attempts integer not null, blocked_until timestamp(6), id bigint generated by default as identity, updated_at timestamp(6) not null, "key" varchar(255), primary key (id));
create table if not exists boards (city_hall_id uuid, id uuid not null, sector_id uuid, name varchar(255), primary key (id));
create table if not exists chat_participants (joined_at timestamp(6), chat_id uuid, employee_id uuid, id uuid not null, role varchar(255) check ((role in ('OWNER','ADMIN','MEMBER'))), primary key (id), unique (chat_id, employee_id));
create table if not exists chats (created_at timestamp(6), city_hall_id uuid, id uuid not null, title varchar(255), type varchar(255) check ((type in ('PRIVATE','GROUP'))), primary key (id));
create table if not exists cityhalls (is_active boolean not null, created_at timestamp(6), updated_at timestamp(6), id uuid not null, state_id uuid not null, cnpj varchar(255) unique, name varchar(255), primary key (id));
create table if not exists client_service_records (service_date date, created_at timestamp(6), client_id uuid not null, created_by_id uuid, id uuid not null, area varchar(140) not null, description varchar(280) not null, observation varchar(2000), primary key (id));
create table if not exists commitments (reserved_value numeric(15,2) not null, created_at timestamp(6), updated_at timestamp(6), contract_id uuid not null, execution_order_id uuid, id uuid not null, issued_by_id uuid not null, commitment_number varchar(255) not null unique, type varchar(255) not null check ((type in ('ORDINARY','ESTIMATED','GLOBAL'))), primary key (id));
create table if not exists contracts (end_date date, signed_at date, start_date date, total_value numeric(15,2) not null, created_at timestamp(6), updated_at timestamp(6), id uuid not null, licitation_process_id uuid not null unique, responsible_id uuid not null, supplier_id uuid not null, contract_number varchar(255) not null unique, object_description TEXT not null, status varchar(255) not null check ((status in ('DRAFT','ACTIVE','FINISHED','CANCELED','SUSPENDED'))), primary key (id));
create table if not exists cross_sector_task_requests (deadline date, answered_at timestamp(6), created_at timestamp(6), answered_by_id uuid, city_hall_id uuid not null, destination_sector_id uuid not null, generated_task_id uuid unique, id uuid not null, origin_sector_id uuid not null, requested_by_id uuid not null, priority varchar(20) not null check ((priority in ('LOW','NORMAL','HIGH','URGENT'))), status varchar(20) not null check ((status in ('PENDING','ACCEPTED','REJECTED','CANCELLED'))), title varchar(160) not null, description TEXT, feedback TEXT, primary key (id));
create table if not exists employees (hours_worked float(53), requisition_status smallint check ((requisition_status between 0 and 2)), salary float(53), admission_date timestamp(6), dismissal_date timestamp(6), city_hall_id uuid, id uuid not null, occupation_id_id uuid, sector_id uuid, registration_number varchar(255), primary key (id));
create table if not exists etps (id uuid not null, requisition_id uuid unique, content varchar(255), primary key (id));
create table if not exists execution_orders (issued_at date not null, created_at timestamp(6), contract_id uuid not null, id uuid not null, issued_by_id uuid not null, description TEXT not null, number varchar(255) not null unique, type varchar(255) not null check ((type in ('SUPPLY','SERVICE'))), primary key (id));
create table if not exists import_batches (created_records integer not null, failed_rows integer not null, ignored_rows integer not null, successful_rows integer not null, total_rows integer not null, updated_records integer not null, created_at timestamp(6), updated_at timestamp(6), city_hall_id uuid not null, id uuid not null, uploaded_by_id uuid not null, status varchar(30) not null check ((status in ('UPLOADED','VALIDATED','VALIDATION_FAILED','IMPORTED','IMPORT_FAILED'))), target_module varchar(30) not null, import_mode varchar(255) check ((import_mode in ('CREATE','UPDATE','UPSERT'))), original_file_name varchar(255) not null, headers_json TEXT not null, mapping_json TEXT, original_file oid not null, report_json TEXT, rows_json TEXT not null, primary key (id));
create table if not exists inbox_entries (created_at timestamp(6), read_at timestamp(6), updated_at timestamp(6), assigned_to_id uuid, city_hall_id uuid not null, created_by_id uuid, destination_employee_id uuid, destination_sector_id uuid, id uuid not null, object_id uuid, priority varchar(20) not null check ((priority in ('LOW','NORMAL','HIGH'))), status varchar(20) not null check ((status in ('NEW','IN_PROGRESS','COMPLETED','ARCHIVED'))), type varchar(20) not null check ((type in ('DOCUMENT','ALERT','REQUEST','TASK'))), object_type varchar(80), tool_slug varchar(80), title varchar(180) not null, entry_key varchar(240), url varchar(300), description TEXT, primary key (id), constraint inbox_city_key_uk unique (city_hall_id, entry_key));
create table if not exists job_levels (level smallint check ((level between 0 and 4)), created_at timestamp(6), updated_at timestamp(6), id uuid not null, sector_id_id uuid, description varchar(255), name varchar(255), types varchar(255) check ((types in ('CARGO_COMISSAO','CONCURSADO','TERCEIRIZADO'))), primary key (id));
create table if not exists licitation_histories (changed_at timestamp(6) not null, created_at timestamp(6), changed_by_id uuid not null, id uuid not null, licitation_process_id uuid not null, event_type varchar(255) not null check ((event_type in ('PROCESS_CREATED','NOTICE_CREATED','STATUS_CHANGED','NOTICE_PUBLISHED','CONTRACT_CREATED','PROCESS_OPENED','PROCESS_FINISHED','PROCESS_CANCELED'))), observation TEXT, status varchar(255) not null check ((status in ('DRAFT','OPEN','IN_PROGRESS','FINISHED','IMPUGNED','POSTPONED','CLOSED','CANCELED'))), primary key (id));
create table if not exists licitation_processes (closing_date date, estimated_value numeric(38,2), opening_date date, created_at timestamp(6), updated_at timestamp(6), id uuid not null, requisition_id uuid not null unique, responsible_id uuid, winner_supplier_id uuid, object_description TEXT, process_number varchar(255), status varchar(255) check ((status in ('DRAFT','OPEN','IN_PROGRESS','FINISHED','IMPUGNED','POSTPONED','CLOSED','CANCELED'))), type varchar(255) check ((type in ('CHAMADA_PUBLICA','CONCORRENCIA_PUBLICA','CONVITES_NP','EXTRATO_FOMENTO','PREGAO_ELETRONICO','PREGAO_PRESENCIAL','TOMADA_PRECOS','OUTROS','CONCORRENCIA','DISPENSA','INEXIGIBILIDADE'))), primary key (id));
create table if not exists message_attachments (size_bytes bigint not null, id uuid not null, message_id uuid not null unique, content_type varchar(120) not null, original_name varchar(255) not null, content oid not null, primary key (id));
create table if not exists messages (sent_at timestamp(6), chat_id uuid not null, id uuid not null, sender_id uuid not null, content TEXT not null, primary key (id));
create table if not exists municipal_clients (created_at timestamp(6), updated_at timestamp(6), city_hall_id uuid not null, id uuid not null, cpf_lookup varchar(80) not null, nickname varchar(100), full_name varchar(180) not null, caf varchar(500), cpf varchar(500) not null, phone varchar(500) not null, secondary_contact varchar(500), state_registration varchar(500), address varchar(1000), primary key (id), constraint client_city_cpf_uk unique (city_hall_id, cpf_lookup));
create table if not exists municipal_document_destinations (document_id uuid not null, employee_id uuid not null, primary key (document_id, employee_id));
create table if not exists municipal_documents (created_at timestamp(6), signed_at timestamp(6), size_bytes bigint not null, updated_at timestamp(6), city_hall_id uuid not null, id uuid not null, owner_id uuid not null, sector_id uuid, signed_by_id uuid, source_id uuid, signature_status varchar(20) not null check ((signature_status in ('NONE','HOMOLOGATION'))), visibility varchar(20) not null check ((visibility in ('PERSONAL','SECTOR','CITY_HALL'))), document_type varchar(60) not null, source_type varchar(80), content_type varchar(120) not null, title varchar(180) not null, source_url varchar(300), description TEXT, original_name varchar(255) not null, content oid not null, primary key (id));
create table if not exists notice_impugnations (created_at timestamp(6), responded_at timestamp(6), id uuid not null, notice_id uuid not null, responded_by_id uuid, supplier_id uuid not null, description TEXT not null, reason varchar(255) not null check ((reason in ('RESTRICTIVE_REQUIREMENT','ILLEGAL_CLAUSE','TECHNICAL_ERROR','DEADLINE_IRREGULARITY','OBJECT_DESCRIPTION_ERROR','OTHER'))), response TEXT, status varchar(255) not null check ((status in ('PENDING','ACCEPTED','REJECTED'))), primary key (id));
create table if not exists notices (estimated_value numeric(15,2) not null, proposal_closing_date date not null, proposal_opening_date date not null, publication_date date not null, created_at timestamp(6), updated_at timestamp(6), created_by_id uuid not null, id uuid not null, licitation_process_id uuid not null unique, content TEXT, notice_number varchar(255) not null unique, object_description TEXT not null, status varchar(255) not null check ((status in ('DRAFT','UNDER_REVIEW','PUBLISHED','IMPUGNED','SUSPENDED','CLOSED','CANCELED'))), title varchar(255) not null, primary key (id));
create table if not exists payment_declarations (secretary_approved boolean not null, created_at timestamp(6), updated_at timestamp(6), approved_by_id uuid not null, commitment_id uuid not null, id uuid not null, description TEXT not null, type varchar(255) not null check ((type in ('ITEM_RECEIPT','SERVICE_MEASUREMENT','PAYMENT_AUTHORIZATION'))), primary key (id));
create table if not exists payments (paid_at date not null, payment_value numeric(15,2) not null, treasury_approved boolean not null, created_at timestamp(6), updated_at timestamp(6), approved_by_id uuid not null, declaration_id uuid not null, id uuid not null, treasury_responsible_id uuid not null, treasury_sector_id uuid not null, primary key (id));
create table if not exists permissions (created_at timestamp(6), updated_at timestamp(6), id uuid not null, resource varchar(255), action smallint array, primary key (id));
create table if not exists permissions_job_level (occupation_id uuid not null, permission_id uuid not null, primary key (occupation_id, permission_id));
create table if not exists process_histories (changed_at timestamp(6) not null, created_at timestamp(6) not null, changed_by_id uuid not null, id uuid not null, requisition_id uuid not null, event_type varchar(255) not null check ((event_type in ('REQUISITION_CREATED','STAGE_SENT','APPROVAL_REQUESTED','APPROVED','REJECTED','COMMENT_ADDED'))), observation TEXT, stage varchar(255) not null check ((stage in ('REQUISICAO_CADASTRADA','HOMOLOGACAO_SECRETARIO','RECEBIMENTO_COMPRAS','ANALISE_REQUISICAO','HOMOLOGACAO_COMPRAS','COMPOSICAO_PROCESSO','PROCESSO_LICITATORIO','SETOR_CONTRATOS','INICIO_SERVICOS','EMISSAO_EMPENHO','DECLARACAO_PAGAMENTO','EXECUCAO_PAGAMENTO','PRESTACAO_CONTAS','ANALISE_PRESTACAO_CONTAS','HOMOLOGACAO_PRESTACAO_CONTAS'))), primary key (id));
create table if not exists proposals (proposed_value numeric(15,2) not null, created_at timestamp(6), submitted_at timestamp(6), updated_at timestamp(6), id uuid not null, licitation_process_id uuid not null, supplier_id uuid not null, impugnation_details TEXT, impugnation_reason varchar(255) check ((impugnation_reason in ('MISSING_DOCUMENTATION','INVALID_CERTIFICATE','TAX_IRREGULARITY','TECHNICAL_NONCOMPLIANCE','DEADLINE_VIOLATION','PRICE_INEXEQUIBLE','OTHER'))), observation TEXT, status varchar(255) not null check ((status in ('SUBMITTED','UNDER_REVIEW','CLASSIFIED','DISQUALIFIED','IMPUGNED','WINNER','REJECTED'))), primary key (id));
create table if not exists requisitions (requires_etp boolean not null, created_at timestamp(6), updated_at timestamp(6), id uuid not null, procurement_responsible_id uuid, responsible_id uuid, sector_id uuid, budget_allocation varchar(255), justification varchar(255), register_number varchar(255), request_status varchar(255) check ((request_status in ('CADASTRADA','APROVADA','CORRECAO','REPROVADA','CANCELADA'))), technical_description varchar(255), type varchar(255) check ((type in ('BEM_MOVEL','BEM_IMOVEL','SERVICO_PJ','EMENDA_IMPOSITIVA'))), primary key (id));
create table if not exists sector_tools (created_at timestamp(6), updated_at timestamp(6), sector_id uuid not null, tools_id uuid not null, primary key (sector_id, tools_id));
create table if not exists sectors (active boolean not null, created_at timestamp(6), updated_at timestamp(6), city_hall_id uuid, id uuid not null, occupation_id_id uuid, description varchar(1000), name varchar(255) not null, primary key (id));
create table if not exists sectors_sector_tools (sector_id uuid not null, sector_tools_sector_id uuid not null, sector_tools_tools_id uuid not null, unique (sector_tools_sector_id, sector_tools_tools_id));
create table if not exists states (uf smallint check ((uf between 0 and 26)), id uuid not null, name varchar(255), primary key (id));
create table if not exists suppliers (active boolean not null, state varchar(2) not null, created_at timestamp(6), updated_at timestamp(6), zip_code varchar(9) not null, id uuid not null, cnpj varchar(18) not null unique, phone varchar(20) not null, city varchar(255) not null, complement varchar(255), corporate_name varchar(255) not null, district varchar(255) not null, email varchar(255) not null, legal_representative varchar(255) not null, number varchar(255) not null, street varchar(255) not null, trade_name varchar(255) not null, primary key (id));
create table if not exists task_attachments (created_at timestamp(6), size bigint not null, id uuid not null, task_id uuid not null, uploaded_by_id uuid, content_type varchar(120) not null, original_name varchar(255) not null, content oid not null, primary key (id));
create table if not exists task_checklist_items (completed boolean not null, item_order integer not null, completed_at timestamp(6), created_at timestamp(6), completed_by_id uuid, id uuid not null, task_id uuid not null, title varchar(180) not null, primary key (id));
create table if not exists task_comments (created_at timestamp(6), edited_at timestamp(6), author_id uuid, id uuid not null, task_id uuid not null, text varchar(2000) not null, primary key (id));
create table if not exists task_responsibles (employee_id uuid not null, task_id uuid not null, constraint task_responsible_uk primary key (task_id, employee_id));
create table if not exists task_time_entries (manual boolean not null, reference_date date, created_at timestamp(6), duration_seconds bigint not null, finished_at timestamp(6), started_at timestamp(6), employee_id uuid not null, id uuid not null, task_id uuid not null, observation varchar(500), primary key (id));
create table if not exists tasks (business_points integer not null, completed_at timestamp(6), created_at timestamp(6), end_date timestamp(6), start_date timestamp(6), updated_at timestamp(6), board_id uuid, created_by_id uuid, id uuid not null, responsible_id uuid, priority varchar(20) not null check ((priority in ('LOW','NORMAL','HIGH','URGENT'))), status varchar(20) not null check ((status in ('TODO','IN_PROGRESS','IN_REVIEW','COMPLETED'))), protocol varchar(60), description varchar(255), expected_result TEXT, title varchar(255), primary key (id));
create table if not exists tool_configurations (enabled boolean not null, mandatory boolean not null, restricted boolean not null, city_hall_id uuid not null, id uuid not null, category varchar(60) not null, icon varchar(80) not null, slug varchar(80) not null, name varchar(120) not null, route varchar(120), description varchar(280) not null, primary key (id), constraint tool_city_slug_uk unique (city_hall_id, slug));
create table if not exists tool_permission_rules (enabled boolean not null, city_hall_id uuid not null, employee_id uuid, id uuid not null, occupation_id uuid, sector_id uuid, level varchar(20) not null check ((level in ('VIEW','MANAGE','ADMIN'))), tool_slug varchar(80) not null, primary key (id));
create table if not exists tools (id uuid not null, name varchar(255), primary key (id));
create table if not exists two_factor_code (expiration timestamp(6) not null, code varchar(255) not null, email varchar(255) not null, primary key (email));
create table if not exists user_sessions (created_at timestamp(6), expires_at timestamp(6), last_activity timestamp(6), revoked_at timestamp(6), id uuid not null, user_id uuid not null, device_type varchar(20), browser varchar(60), operating_system varchar(60), refresh_token_hash varchar(64) not null, ip_address varchar(80), user_agent varchar(500), primary key (id));
create table if not exists user_tool_favorites (employee_id uuid not null, id uuid not null, tool_slug varchar(80) not null, primary key (id), constraint favorite_employee_slug_uk unique (employee_id, tool_slug));
create table if not exists users (accept_terms boolean, accessibility boolean, status boolean, two_factor boolean, created_at timestamp(6), last_login timestamp(6), updated_at timestamp(6), id uuid not null, password varchar(2000) not null, avatar_path varchar(255), cpf varchar(255) unique, email varchar(255) unique, first_name varchar(255), last_name varchar(255), phone varchar(255) unique, role varchar(255) not null check ((role in ('EMPLOYEE','CITIZEN','ADMIN'))), primary key (id));
create table if not exists workflow_status (created_at timestamp(6), finished_at timestamp(6), started_at timestamp(6), updated_at timestamp(6), id uuid not null, requisition_id uuid unique, responsible_id uuid, observation varchar(255), stage varchar(255) check ((stage in ('REQUISICAO_CADASTRADA','HOMOLOGACAO_SECRETARIO','RECEBIMENTO_COMPRAS','ANALISE_REQUISICAO','HOMOLOGACAO_COMPRAS','COMPOSICAO_PROCESSO','PROCESSO_LICITATORIO','SETOR_CONTRATOS','INICIO_SERVICOS','EMISSAO_EMPENHO','DECLARACAO_PAGAMENTO','EXECUCAO_PAGAMENTO','PRESTACAO_CONTAS','ANALISE_PRESTACAO_CONTAS','HOMOLOGACAO_PRESTACAO_CONTAS'))), primary key (id));
create index if not exists agenda_city_dates_idx on agenda_events (city_hall_id, start_date, end_date);
create index if not exists audit_city_created_idx on audit_events (city_hall_id, created_at);
create index if not exists inbox_city_created_idx on inbox_entries (city_hall_id, created_at);
create index if not exists inbox_employee_status_idx on inbox_entries (destination_employee_id, status);
create index if not exists client_city_name_idx on municipal_clients (city_hall_id, full_name);
create index if not exists document_city_created_idx on municipal_documents (city_hall_id, created_at);
create index if not exists checklist_task_order_idx on task_checklist_items (task_id, item_order);
create index if not exists time_employee_active_idx on task_time_entries (employee_id, manual, finished_at);
create index if not exists session_user_active_idx on user_sessions (user_id, revoked_at);

-- Colunas adicionadas a tabelas que podem existir em instalacoes anteriores.
alter table if exists sectors add column if not exists description varchar(1000) default '';
alter table if exists sectors add column if not exists active boolean default true not null;
alter table if exists tasks add column if not exists status varchar(20) default 'TODO' not null;
alter table if exists tasks add column if not exists priority varchar(20) default 'NORMAL' not null;
alter table if exists tasks add column if not exists business_points integer default 0 not null;
alter table if exists tasks add column if not exists protocol varchar(60) default '';
alter table if exists tasks add column if not exists expected_result text default '';
alter table if exists tasks add column if not exists completed_at timestamp(6);
